pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address holder) public {
        vm.assume(holder != address(0));
        vm.assume(holder != address(c));
        // Adversarial counterparty: a re-entrant holder whose receive() calls back into NETM.
        // This is needed because the bug is about NETM, and an external party may trigger
        // re-entrancy that affects balances.
        ReentrantCaller helper = new ReentrantCaller();

        // Record initial state
        uint256 initTotal = c.totalDistributed();
        address owner = c.owner();

        // Drive c through NETM. We make the call from the helper, so the helper calls back.
        // That alone does not exploit the double-assign; but we also allow the fuzzer to choose
        // 'holder', and we check the sum of their balances afterwards.
        vm.prank(address(helper));
        c.NETM();

        // After NETM, totalDistributed does NOT change (NETM does not mint).
        // The sum of owner and holder balances must equal totalDistributed.
        // The mutant double-assigns owner balance, so sum > totalDistributed.
        uint256 ownerBal = c.balanceOf(owner);
        uint256 holderBal = c.balanceOf(holder);
        assertTrue(ownerBal + holderBal == initTotal);
    }
}

contract ReentrantCaller {
    C target;
    function setTarget(C _c) external { target = _c; }
    function callNETM() external { target.NETM(); }
    fallback() external payable { } // needed to deploy
}

