pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 distributeAmount, address recipient) public {
        // Keep distributeAmount within the totalDistributed of 250,000,000e18 so distr doesn't push distributed over supply
        // The NETM function gives the owner totalDistributed balance without touching totalRemaining or totalDistributed
        vm.assume(distributeAmount > 0 && distributeAmount <= 250000000e18);
        vm.assume(recipient != address(0) && recipient != address(this));

        // Call NETM as owner to set up initial balances
        vm.prank(c.owner());
        c.NETM();

        // Perform a token distribution to bring totalDistributed closer to totalSupply
        vm.prank(c.owner());
        c.finishDistribution(); // finish distribution so we can call distr via getTokens

        // Actually we need to call distr. Since finishDistribution blocks distr, we call getTokens which invokes distr
        // getTokens is canDistr, so we need distributionFinished false. We revert finishDistribution assumption.
        // Instead, we work with the mutable state directly: we can call distr by calling getTokens after setting value.
        // Or we can directly transfer tokens to simulate distributions.
        // Simpler: transfer tokens to recipient to increase sum of balances.
        vm.prank(c.owner());
        c.transfer(recipient, distributeAmount);

        // Now calculate sum of balances for all addresses that have ever received tokens.
        // We know owner, recipient, and address(0) if buggy.
        uint256 sumBalances = c.balanceOf(c.owner()) + c.balanceOf(recipient) + c.balanceOf(address(0));

        // The invariant: totalSupply equals sum of all balances.
        assertEq(c.totalSupply(), sumBalances);
    }
}

