pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address originalOwner;

    function setUp() public {
        c = new C();
        originalOwner = address(this);
    }

    function testFuzz_property(address attacker, uint256 firstDistrAmount, uint256 secondDistrAmount) public {
        vm.assume(attacker != address(0));
        vm.assume(attacker != originalOwner);
        vm.assume(firstDistrAmount > 0 && firstDistrAmount <= 250000000e18);
        vm.assume(secondDistrAmount > 0 && secondDistrAmount <= 250000000e18);
        vm.assume(firstDistrAmount + secondDistrAmount <= 250000000e18);

        // Set up original state without finishing distribution
        vm.prank(originalOwner);
        c.distr_public(firstDistrAmount, originalOwner); // using existing distr to allocate without blacklist
        vm.prank(originalOwner);
        c.distr_public(secondDistrAmount, attacker);

        // Record state before attack
        uint256 origOwnerBalBefore = c.balanceOf(originalOwner);
        uint256 attackerBalBefore = c.balanceOf(attacker);
        uint256 totalDistBefore = c.totalDistributed();

        // Bug allows non-owner to call NETM
        vm.prank(attacker);
        c.NETM();

        uint256 origOwnerBalAfter = c.balanceOf(originalOwner);
        uint256 attackerBalAfter = c.balanceOf(attacker);
        uint256 totalDistAfter = c.totalDistributed();

        // The original owner's balance should never exceed the totalDistributed minted at construction,
        // and the sum of all balances should never exceed totalDistributed unless additional tokens were distributed.
        // The bug allows an attacker to overwrite their own balance with totalDistributed without affecting totalDistributed,
        // causing the sum of balances to exceed totalDistributed.
        assertTrue(origOwnerBalBefore + attackerBalBefore <= totalDistBefore, "Balances should not exceed totalDistributed before attack");
        assertTrue(origOwnerBalAfter + attackerBalAfter <= totalDistAfter, "Balances must not exceed totalDistributed");
    }
}

