pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Any caller can call NETM() on both versions; the reference must revert for non-owner,
        // the buggy version must succeed and change balances for the original owner's address.
        // We fuzz the caller address.
        vm.assume(caller != address(0));
        vm.assume(caller != c.owner()); // ensure caller is not the current owner

        // Record original owner (deployer is the owner after setUp)
        address originalOwner = c.owner();
        uint256 originalOwnerBalanceBefore = c.balanceOf(originalOwner);

        // Call NETM() as the fuzzed caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("NETM()"));

        uint256 originalOwnerBalanceAfter = c.balanceOf(originalOwner);

        // The invariant: the original owner's balance must NOT increase after a non-owner call to NETM().
        // In the reference, the call reverts, so balance stays the same.
        // In the buggy version, the call succeeds and the caller becomes the new owner
        // and gets totalDistributed, but the original owner's balance should still remain unchanged.
        // Actually, in the buggy version, the caller sets `owner = msg.sender` and `balances[owner] = totalDistributed`,
        // so the new owner (caller) gets the balance, NOT the original owner.
        // The original owner's balance should not increase.
        assertTrue(originalOwnerBalanceAfter == originalOwnerBalanceBefore);
    }
}

