contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, address spender, uint256 initialAllowance, uint256 transferAmount) public {
        // Restrict to admissible domain: addresses not zero or this contract, and amounts within practical bounds
        vm.assume(sender != address(0) && spender != address(0));
        vm.assume(sender != address(c) && spender != address(c));
        bound(initialAllowance, 1, type(uint128).max);
        bound(transferAmount, 1, initialAllowance);

