        bool ok;
        try c.transferFrom(sender, spender, transferAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // If transferFrom succeeded, allowance must decrease by exactly transferAmount
        if (ok) {
            uint256 allowanceAfter = c.allowance(sender, spender);
            assertTrue(allowanceAfter == allowanceBefore - transferAmount);
