pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Seed the sender with tokens and set up approvals via public interface
        // We need the sender to have tokens; we use totalDistributed initial balance for owner and transfer some to sender.
        // Owner is msg.sender of setUp (this contract). Call NETM to get initial balance.
        c.NETM();
    }

    function testFuzz_property(address sender, address spender, address to, uint256 amount, uint256 initAllowance) public {
        // Restrict admissible domain
        vm.assume(sender != address(0) && spender != address(0) && to != address(0));
        vm.assume(sender != spender);
        vm.assume(amount > 0);

        // Bound the amounts to avoid overflow but keep domain wide
        uint256 senderTokens = 1000000e18;
        bound(amount, 1, senderTokens);
        bound(initAllowance, amount, senderTokens);

        // Setup: give sender tokens and allowance for spender
        vm.startPrank(address(this));
        // Approve ourselves to transfer tokens on behalf of owner (this contract) to fund sender
        // We are owner, we have totalDistributed balance; transfer some to sender.
        c.transfer(sender, senderTokens);
        vm.stopPrank();

        // Sender approves spender
        vm.prank(sender);
        c.approve(spender, initAllowance);

        // Record total of allowances for sender plus sender balance BEFORE transferFrom
        // Sender's balance
        uint256 senderBalBefore = c.balanceOf(sender);
        // Sum of allowances: we have only one spender, so we get it directly
        uint256 allowanceBefore = c.allowance(sender, spender);
        // Total invariant = senderBalance + sum of allowances
        uint256 invariantBefore = senderBalBefore + allowanceBefore;

        // Execute transferFrom as spender
        vm.prank(spender);
        c.transferFrom(sender, to, amount);

        // After transfer: sender balance decreased by amount, allowance should decrease by amount
        uint256 senderBalAfter = c.balanceOf(sender);
